    maps: groups(groups: ["maps"]) {
      id
      ...SportGroup
      templates(includeEmpty: false) {
        id
        extId
        markets {
          status
          specifiers
          extId
        }
      }
    }
    ...UfcFrontRowSeat
    group: groups(groups: $groups) {
      ...SportGroup
      templates(includeEmpty: false) {
        id
        ...SportGroupTemplate
        markets {
          ...SportMarket
          outcomes {
            ...SportMarketOutcome
